SELECT FROM sys_notice n LEFT JOIN sys_user u ON u.user_id = n.publisher_id WHERE n.status = 1
AND n.title LIKE CONCAT('%', #{title}, '%')
AND n.type = #{type}
AND n.publish_time >= #{beginTime}
AND n.publish_time <= CONCAT(#{endTime}, ' 23:59:59')
ORDER BY n.top_flag DESC, n.publish_time DESC

SELECT notice_id, title, content, type, top_flag, status, publisher_id, publish_time
FROM sys_notice
WHERE notice_id = #{noticeId}

mapper.update:
UPDATE sys_notice
SET title = #{title}, content = #{content}, type = #{type},
    top_flag = #{topFlag}, status = #{status}
WHERE notice_id = #{noticeId}
